/* Outline v08: save immutable syllabus snapshots from the final review step. */
(function(){
  const course=()=>{try{return localStorage.getItem('ai-jiaowu-current-course')||'discrete'}catch{return 'discrete'}};
  const storeKey=()=>`ai-jiaowu-syllabus-saved-versions-${course()}`;
  const read=()=>{try{const v=JSON.parse(localStorage.getItem(storeKey())||'[]');return Array.isArray(v)?v:[]}catch{return []}};
  const write=v=>{try{localStorage.setItem(storeKey(),JSON.stringify(v.slice(-20)))}catch{}};
  const hydrate=()=>{if(location.hash!=='#course/syllabus')return;const select=document.querySelector('.syllabus-head-actions select[aria-label="大纲版本"]');if(!select)return;const current=localStorage.getItem('ai-jiaowu-syllabus-outline-version')||'v3 · 当前编辑',saved=read(),unique=[...new Map(saved.map(v=>[v.id,v])).values()];select.innerHTML='<option value="v3 · 当前编辑">v3 · 当前编辑</option>'+unique.map(v=>'<option value="'+v.id+'">'+v.id+' · 已保存 '+v.time+'</option>').join('');if([...select.options].some(o=>o.value===current))select.value=current};
  window.saveSyllabusVersion=()=>{const active=document.querySelector('[data-outline-section]')?.dataset.outlineSection;window.saveOutlineSection?.(active||'reference',false);const id='v'+(3+read().length+1),now=new Date(),time=now.toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})+' '+now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});let fields=null,state=null,chapters=null;try{fields=localStorage.getItem(`ai-jiaowu-syllabus-outline-fields-v2-${course()}`);state=localStorage.getItem(`ai-jiaowu-syllabus-outline-state-v2-${course()}`);chapters=localStorage.getItem('ai-jiaowu-syllabus-demo')}catch{};const versions=read();versions.push({id,time,fields,state,chapters});write(versions);try{localStorage.setItem('ai-jiaowu-syllabus-outline-version',id)}catch{};if(window.showSyllabusToast)window.showSyllabusToast(id+' 已保存完整 01–08 内容，可在右上角切换查看');if(window.render)window.render();setTimeout(hydrate,80)};
  const install=()=>{if(location.hash!=='#course/syllabus')return;const root=document.querySelector('[data-outline-section]');root?.querySelectorAll('.outline-section-actions button').forEach(b=>{if(['保存版本','保存草稿'].includes(b.textContent.trim()))b.remove()});document.querySelectorAll('.syllabus-head-actions select[aria-label="大纲版本"], .syllabus-head-actions button.syllabus-top-save').forEach(el=>el.remove());};
  const original=window.selectOutlineVersion;window.selectOutlineVersion=v=>{const saved=read().find(x=>x.id===v);if(saved){try{if(saved.fields)localStorage.setItem(`ai-jiaowu-syllabus-outline-fields-v2-${course()}`,saved.fields);if(saved.state)localStorage.setItem(`ai-jiaowu-syllabus-outline-state-v2-${course()}`,saved.state);if(saved.chapters)localStorage.setItem('ai-jiaowu-syllabus-demo',saved.chapters);localStorage.setItem('ai-jiaowu-syllabus-outline-version',v)}catch{};if(window.showSyllabusToast)window.showSyllabusToast('已切换到 '+v+'，正在载入该版本内容');setTimeout(()=>location.reload(),80);return}original?.(v)};
  const style=document.createElement('style');style.textContent='.syllabus-head-actions .syllabus-top-save,.syllabus-head-actions button[data-preview-trigger],.syllabus-head-actions .btn.secondary{background:#0b9c8c;border-color:#0b9c8c;color:#fff}.syllabus-head-actions .syllabus-top-save:hover,.syllabus-head-actions button[data-preview-trigger]:hover,.syllabus-head-actions .btn.secondary:hover{background:#087c72;border-color:#087c72;color:#fff}.syllabus-head-actions .syllabus-top-save:focus-visible,.syllabus-head-actions button[data-preview-trigger]:focus-visible,.syllabus-head-actions .btn.secondary:focus-visible{outline:2px solid #bdebe3;outline-offset:2px}';document.head.appendChild(style);setInterval(install,1200);setTimeout(install,150);
})();

