/* Recalculate chapter completeness from every required editable field. */
(function(){
  const details=()=>{try{return JSON.parse(localStorage.getItem('ai-jiaowu-syllabus-chapter-details-discrete')||'{}')}catch{return {}}};
  const complete=ch=>{const d=Object.assign({},ch,details()[ch?.id]||{}),home=Array.isArray(d.homework)?d.homework.filter(Boolean).length:String(d.homework||'').trim().length;return ['code','title','hours','content','keyPoints','difficultPoints','requirements'].every(k=>String(d[k]??'').trim())&&!!home};
  const sync=()=>{if(location.hash!=='#course/syllabus')return;const list=window.__syllabusChapters||[],map=new Map();list.forEach((p,ci)=>{map.set(ci+':p',p);(p.children||[]).forEach((c,si)=>{map.set(ci+':'+si,c);(c.children||[]).forEach((g,gi)=>map.set(ci+':'+si+':'+gi,g))})});document.querySelectorAll('#syllabusTree .chapter-row').forEach(row=>{const ci=Number(row.dataset.chapterIndex),si=row.classList.contains('child')?Number(row.dataset.childIndex):null,gi=row.classList.contains('grandchild')?Number(row.dataset.grandchildIndex):null,ch=gi!=null?map.get(ci+':'+si+':'+gi):si!=null?map.get(ci+':'+si):map.get(ci+':p');if(!ch)return;const tags=[...row.querySelectorAll(':scope>.chapter-complete-tag')];let tag=tags[0];tags.slice(1).forEach(x=>x.remove());if(!tag){tag=document.createElement('span');tag.className='chapter-complete-tag';row.appendChild(tag)}const ok=complete(ch);tag.classList.toggle('is-complete',ok);tag.classList.toggle('is-pending',!ok);tag.textContent=ok?'已完善':'待完善'});};
  setInterval(sync,2400);window.addEventListener('hashchange',()=>setTimeout(sync,120));setTimeout(sync,120);
})();

